content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_deadball_break",
 "name": "Deadball: the stretch",
 "set": "set_ksab5_desk",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Lead anchor"
  },
  "b": {
   "mark": "b",
   "label": "Analyst"
  }
 },
 "wallText": "{status}",
 "wallSub": "KSAB5 Sports",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "jib",
    "frame": "full",
    "on": [
     "a",
     "b"
    ],
    "move": "crane",
    "cut": "dissolve"
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ],
   "hold": 2.4,
   "wall": "feed"
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Time to stretch. It's {away} {awayScore}, {home} {homeScore} after six and a half.",
     "Seventh-inning stretch. {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "That's {homersSaid} so far. {lastHomer.name} hit the latest in the {lastHomer.inning}."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "Home runs",
     "list": "homers",
     "row": "{player}: {inning}",
     "limit": 6,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "homerCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "No home runs tonight. {hits} hits and they've all stayed in the park.",
     "It's been small ball all night. {hits} hits, none of them over the wall."
    ]
   },
   "gfx": [
    {
     "kind": "box",
     "source": "feed",
     "title": "Live: {venue}",
     "side": "right",
     "at": 0,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "homerCount",
     "op": "=",
     "value": 0
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam2",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "{gameStar.name} is having a night. {gameStar.tonight}."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "gameStar",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "gameStar",
     "op": "has"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Back to {announcer} for the {nextOrd}.",
     "Here comes the {nextOrd}. {announcer}, it's yours."
    ]
   },
   "gfx": [],
   "wall": "feed"
  }
 ]
}
